static void test_pslog_runtime_log_name(const char *msg) {
  if (msg != NULL && strncmp(msg, "agent ", sizeof("agent ") - 1U) == 0) {
    g_test_agent_runtime_legacy_log_name_count++;
  }
}

static void test_pslog_infof(pslog_logger *log, const char *msg,
                             const char *kvfmt, ...) {
  va_list args;

  (void)log;
  test_pslog_runtime_log_name(msg);
  va_start(args, kvfmt);
  va_end(args);
  if (kvfmt != NULL) {
    g_test_infof_count++;
  }
}

static void test_pslog_tracef(pslog_logger *log, const char *msg,
                              const char *kvfmt, ...) {
  va_list args;

  (void)log;
  test_pslog_runtime_log_name(msg);
  va_start(args, kvfmt);
  va_end(args);
  if (kvfmt != NULL) {
    g_test_tracef_count++;
  }
}

static void test_pslog_debugf(pslog_logger *log, const char *msg,
                              const char *kvfmt, ...) {
  va_list args;

  (void)log;
  test_pslog_runtime_log_name(msg);
  va_start(args, kvfmt);
  va_end(args);
  if (kvfmt != NULL) {
    g_test_debugf_count++;
    if (msg != NULL && strcmp(msg, "cai.agent.runtime.subagent.start") == 0) {
      (void)snprintf(g_test_subagent_started_kvfmt,
                     sizeof(g_test_subagent_started_kvfmt), "%s", kvfmt);
    }
  }
}

