  sink_callbacks.context = &writer;
  expect_int(state, test_name,
             cai_sink_from_callbacks(&sink_callbacks, &sink, &error), CAI_OK);
  expect_int(state, test_name,
             cai_mcp_client_call_tool(client, "stream", NULL, sink, &error),
             CAI_ERR_SERVER);
