  expect_str(state, "conversation_retrieve_id", conversation->id(conversation),
             "conv_get");
  conversation->close(conversation);
  conversation = NULL;
  expect_int(state, "conversation_from_id",
             cai_conversation_from_id("conv_get", &conversation_ref, &error),
             CAI_OK);
