static void test_terminal_external_child_reap(test_state *state) {
  char dir_template[] = "/tmp/cai-terminal-external-reap-XXXXXX";
  cai_terminal_tool_config config;
  cai_tool_registry *registry;
  cai_sink_callbacks callbacks;
  cai_sink *sink;
  write_state writer;
  cai_error error;
  struct sigaction ignored_action;
  struct sigaction previous_action;
  int sigchld_ignored;
  int rc;
  int i;

  if (mkdtemp(dir_template) == NULL) {
    test_fail(state, "terminal_external_reap_mkdtemp", "mkdtemp failed");
    return;
  }
  memset(&config, 0, sizeof(config));
  memset(&writer, 0, sizeof(writer));
  memset(&ignored_action, 0, sizeof(ignored_action));
  registry = NULL;
  sink = NULL;
  sigchld_ignored = 0;
  rc = CAI_OK;
  cai_error_init(&error);
  config.root_path = dir_template;
  config.default_workdir = dir_template;
  config.default_yield_time_ms = 100L;
  config.max_yield_time_ms = 100L;
  callbacks.write = test_write;
  callbacks.close = test_write_close;
  callbacks.context = &writer;
  expect_int(state, "terminal_external_reap_registry",
             cai_tool_registry_new(&registry, &error), CAI_OK);
  if (registry != NULL) {
    expect_int(
        state, "terminal_external_reap_register",
        cai_tool_registry_register_terminal_tools(registry, &config, &error),
        CAI_OK);
  }
  if (registry != NULL) {
    expect_int(state, "terminal_external_reap_sink",
               cai_sink_from_callbacks(&callbacks, &sink, &error), CAI_OK);
  }
  if (sink != NULL) {
    ignored_action.sa_handler = SIG_IGN;
    if (sigemptyset(&ignored_action.sa_mask) != 0 ||
        sigaction(SIGCHLD, &ignored_action, &previous_action) != 0) {
      test_fail(state, "terminal_external_reap_ignore_sigchld",
                "failed to ignore SIGCHLD");
    } else {
      sigchld_ignored = 1;
      rc = cai_tool_registry_run(registry, CAI_TERMINAL_EXEC_TOOL_NAME,
                                 "{\"cmd\":\"printf reaped\","
                                 "\"yield_time_ms\":100}",
                                 sink, &error);
      expect_int(state, "terminal_external_reap_exec", rc, CAI_OK);
      expect_substr(state, "terminal_external_reap_output", writer.buffer,
                    "reaped");
      /* Output may arrive before the reader's subsequent waitpid() observes
       * ECHILD. Poll through the documented terminal continuation surface so
       * this test validates eventual completion rather than one scheduling
       * order between output and automatic child reaping. */
      for (i = 0; rc == CAI_OK && i < 5 &&
                  strstr(writer.buffer, "\"completed\":true") == NULL;
           i++) {
        writer.buffer[0] = '\0';
        writer.length = 0U;
        rc = cai_tool_registry_run(registry, CAI_TERMINAL_WRITE_TOOL_NAME,
                                   "{\"session_id\":\"terminal-1\","
                                   "\"yield_time_ms\":100}",
                                   sink, &error);
      }
      expect_int(state, "terminal_external_reap_poll", rc, CAI_OK);
      expect_substr(state, "terminal_external_reap_completed", writer.buffer,
                    "\"completed\":true");
      if (strstr(writer.buffer, "\"exit_code\"") != NULL ||
          strstr(writer.buffer, "\"signal\"") != NULL) {
        test_fail(state, "terminal_external_reap_status_unavailable",
                  "externally reaped command reported an unavailable status");
      }
    }
  }
  if (sigchld_ignored) {
    if (sigaction(SIGCHLD, &previous_action, NULL) != 0) {
      test_fail(state, "terminal_external_reap_restore_sigchld",
                "failed to restore SIGCHLD disposition");
    }
  }
  cai_sink_close(sink);
  cai_tool_registry_destroy(registry);
  cai_error_cleanup(&error);
  rmdir(dir_template);
}

static void test_terminal_closes_inherited_fds(test_state *state) {
#if defined(__linux__)
  char dir_template[] = "/tmp/cai-terminal-fd-isolation-XXXXXX";
  char secret_template[] = "/tmp/cai-terminal-fd-secret-XXXXXX";
  static const char secret[] = "model-must-not-read-this-host-secret";
  char request[512];
  cai_terminal_tool_config config;
  cai_tool_registry *registry;
  cai_sink_callbacks callbacks;
  cai_sink *sink;
  write_state writer;
  cai_error error;
  int secret_fd;
  int descriptor_flags;
  int rc;
  int i;

  if (mkdtemp(dir_template) == NULL) {
    test_fail(state, "terminal_fd_isolation_mkdtemp", "mkdtemp failed");
    return;
  }
  secret_fd = mkstemp(secret_template);
  if (secret_fd < 0) {
    test_fail(state, "terminal_fd_isolation_mkstemp", "mkstemp failed");
    rmdir(dir_template);
    return;
  }
  if (write(secret_fd, secret, sizeof(secret) - 1U) !=
          (ssize_t)(sizeof(secret) - 1U) ||
      lseek(secret_fd, 0, SEEK_SET) < 0) {
    test_fail(state, "terminal_fd_isolation_write", "failed to seed secret");
    close(secret_fd);
    unlink(secret_template);
    rmdir(dir_template);
    return;
  }
  descriptor_flags = fcntl(secret_fd, F_GETFD);
  if (descriptor_flags < 0 ||
      fcntl(secret_fd, F_SETFD, descriptor_flags & ~FD_CLOEXEC) != 0) {
    test_fail(state, "terminal_fd_isolation_inheritable",
              "failed to make secret descriptor inheritable");
    close(secret_fd);
    unlink(secret_template);
    rmdir(dir_template);
    return;
  }
  if (snprintf(request, sizeof(request),
               "{\"cmd\":\"if [ -e /proc/self/fd/%d ]; then cat "
               "/proc/self/fd/%d; else printf sealed; fi\","
               "\"yield_time_ms\":100}",
               secret_fd, secret_fd) >= (int)sizeof(request)) {
    test_fail(state, "terminal_fd_isolation_request", "request is too long");
    close(secret_fd);
    unlink(secret_template);
    rmdir(dir_template);
    return;
  }
  memset(&config, 0, sizeof(config));
  memset(&writer, 0, sizeof(writer));
  registry = NULL;
  sink = NULL;
  cai_error_init(&error);
  config.root_path = dir_template;
  config.default_workdir = dir_template;
  config.default_yield_time_ms = 100L;
  config.max_yield_time_ms = 100L;
  callbacks.write = test_write;
  callbacks.close = test_write_close;
  callbacks.context = &writer;
  rc = cai_tool_registry_new(&registry, &error);
  if (rc == CAI_OK) {
    rc = cai_tool_registry_register_terminal_tools(registry, &config, &error);
  }
  if (rc == CAI_OK) {
    rc = cai_sink_from_callbacks(&callbacks, &sink, &error);
  }
  if (rc == CAI_OK) {
    rc = cai_tool_registry_run(registry, CAI_TERMINAL_EXEC_TOOL_NAME, request,
                               sink, &error);
  }
  expect_int(state, "terminal_fd_isolation_exec", rc, CAI_OK);
  for (i = 0; rc == CAI_OK && i < 5 && strstr(writer.buffer, "sealed") == NULL;
       i++) {
    writer.buffer[0] = '\0';
    writer.length = 0U;
    rc = cai_tool_registry_run(registry, CAI_TERMINAL_WRITE_TOOL_NAME,
                               "{\"session_id\":\"terminal-1\","
                               "\"yield_time_ms\":100}",
                               sink, &error);
  }
  expect_int(state, "terminal_fd_isolation_poll", rc, CAI_OK);
  expect_substr(state, "terminal_fd_isolation_sealed", writer.buffer, "sealed");
  expect_int(state, "terminal_fd_isolation_secret_hidden",
             strstr(writer.buffer, secret) == NULL, 1L);
  cai_sink_close(sink);
  cai_tool_registry_destroy(registry);
  cai_error_cleanup(&error);
  close(secret_fd);
  unlink(secret_template);
  rmdir(dir_template);
#else
  (void)state;
#endif
}

static void test_terminal_concurrent_start(test_state *state) {
  char dir_template[] = "/tmp/cai-terminal-race-XXXXXX";
  cai_terminal_tool_config config;
  cai_tool_registry *registry;
  cai_sink_callbacks callbacks;
  cai_sink *sink;
  terminal_race_policy_state policy;
  terminal_race_exec_state first;
  terminal_race_exec_state second;
  pthread_t first_thread;
  pthread_t second_thread;
  write_state writer;
  cai_error error;
  int first_created;
  int second_created;

  if (mkdtemp(dir_template) == NULL) {
    test_fail(state, "terminal_race_mkdtemp", "mkdtemp failed");
    return;
  }
  memset(&config, 0, sizeof(config));
  memset(&policy, 0, sizeof(policy));
  memset(&first, 0, sizeof(first));
  memset(&second, 0, sizeof(second));
  memset(&writer, 0, sizeof(writer));
  registry = NULL;
  sink = NULL;
  first_created = 0;
  second_created = 0;
  cai_error_init(&error);
  config.root_path = dir_template;
  config.default_workdir = dir_template;
  config.default_yield_time_ms = 20L;
  config.max_yield_time_ms = 100L;
  config.policy = test_terminal_race_policy;
  config.policy_context = &policy;
  expect_int(state, "terminal_race_policy_lock",
             pthread_mutex_init(&policy.lock, NULL), 0L);
  expect_int(state, "terminal_race_policy_condition",
             pthread_cond_init(&policy.changed, NULL), 0L);
  expect_int(state, "terminal_race_registry",
             cai_tool_registry_new(&registry, &error), CAI_OK);
  if (registry != NULL) {
    expect_int(
        state, "terminal_race_register",
        cai_tool_registry_register_terminal_tools(registry, &config, &error),
        CAI_OK);
  }
  if (registry != NULL) {
    first.registry = registry;
    second.registry = registry;
    first_created = pthread_create(&first_thread, NULL, test_terminal_race_exec,
                                   &first) == 0;
    second_created = pthread_create(&second_thread, NULL,
                                    test_terminal_race_exec, &second) == 0;
    expect_int(state, "terminal_race_first_thread", first_created, 1L);
    expect_int(state, "terminal_race_second_thread", second_created, 1L);
    if (!first_created || !second_created) {
      pthread_mutex_lock(&policy.lock);
      policy.released = 1;
      pthread_cond_broadcast(&policy.changed);
      pthread_mutex_unlock(&policy.lock);
    }
    if (first_created) {
      pthread_join(first_thread, NULL);
    }
    if (second_created) {
      pthread_join(second_thread, NULL);
    }
    if (first_created && second_created) {
      expect_int(state, "terminal_race_one_success",
                 (first.rc == CAI_OK) + (second.rc == CAI_OK), 1L);
      expect_int(state, "terminal_race_one_rejected",
                 (first.rc == CAI_ERR_INVALID) + (second.rc == CAI_ERR_INVALID),
                 1L);
    }
    cai_error_cleanup(&first.error);
    cai_error_cleanup(&second.error);
    callbacks.write = test_write;
    callbacks.close = test_write_close;
    callbacks.context = &writer;
    expect_int(state, "terminal_race_sink",
               cai_sink_from_callbacks(&callbacks, &sink, &error), CAI_OK);
    if (sink != NULL) {
      expect_int(state, "terminal_race_terminate",
                 cai_tool_registry_run(
                     registry, CAI_TERMINAL_WRITE_TOOL_NAME,
                     "{\"session_id\":\"terminal-1\",\"terminate\":true,"
                     "\"yield_time_ms\":10}",
                     sink, &error),
                 CAI_OK);
    }
  }
  cai_sink_close(sink);
  cai_tool_registry_destroy(registry);
  pthread_cond_destroy(&policy.changed);
  pthread_mutex_destroy(&policy.lock);
  cai_error_cleanup(&error);
  rmdir(dir_template);
}

static void test_terminal_concurrent_operation(test_state *state) {
  char dir_template[] = "/tmp/cai-terminal-operation-XXXXXX";
  cai_terminal_tool_config config;
  cai_tool_registry *registry;
  cai_sink_callbacks callbacks;
  cai_sink *sink;
  terminal_event_state events;
  terminal_write_state write;
  pthread_t write_thread;
  write_state writer;
  cai_error error;
  struct timespec pause_time;
  int write_created;

  if (mkdtemp(dir_template) == NULL) {
    test_fail(state, "terminal_operation_mkdtemp", "mkdtemp failed");
    return;
  }
  memset(&config, 0, sizeof(config));
  memset(&events, 0, sizeof(events));
  memset(&write, 0, sizeof(write));
  memset(&writer, 0, sizeof(writer));
  registry = NULL;
  sink = NULL;
  write_created = 0;
  cai_error_init(&error);
  config.root_path = dir_template;
  config.default_workdir = dir_template;
  config.default_yield_time_ms = 0L;
  config.max_yield_time_ms = 100L;
  config.default_poll_yield_time_ms = 1000L;
  config.max_poll_yield_time_ms = 1000L;
  config.event_callback = test_terminal_event;
  config.event_context = &events;
  expect_int(state, "terminal_operation_registry",
             cai_tool_registry_new(&registry, &error), CAI_OK);
  if (registry != NULL) {
    expect_int(
        state, "terminal_operation_register",
        cai_tool_registry_register_terminal_tools(registry, &config, &error),
        CAI_OK);
  }
  callbacks.write = test_write;
  callbacks.close = test_write_close;
  callbacks.context = &writer;
  if (registry != NULL) {
    expect_int(state, "terminal_operation_sink",
               cai_sink_from_callbacks(&callbacks, &sink, &error), CAI_OK);
  }
  if (registry != NULL && sink != NULL) {
    expect_int(state, "terminal_operation_start",
               cai_tool_registry_run(
                   registry, CAI_TERMINAL_EXEC_TOOL_NAME,
                   "{\"cmd\":\"sleep 1\",\"yield_time_ms\":0}", sink, &error),
               CAI_OK);
    write.registry = registry;
    write_created = pthread_create(&write_thread, NULL,
                                   test_terminal_concurrent_write, &write) == 0;
    expect_int(state, "terminal_operation_thread", write_created, 1L);
    if (write_created) {
      pause_time.tv_sec = 0;
      pause_time.tv_nsec = 100000000L;
      (void)nanosleep(&pause_time, NULL);
      cai_error_cleanup(&error);
      cai_error_init(&error);
      expect_int(state, "terminal_operation_reject_overlap",
                 cai_tool_registry_run(registry, CAI_TERMINAL_EXEC_TOOL_NAME,
                                       "{\"cmd\":\"printf wrong\","
                                       "\"yield_time_ms\":0}",
                                       sink, &error),
                 CAI_ERR_INVALID);
      pthread_join(write_thread, NULL);
      expect_int(state, "terminal_operation_poll", write.rc, CAI_OK);
      expect_str(state, "terminal_operation_completion_command", events.command,
                 "sleep 1");
      expect_int(state, "terminal_operation_completion_id",
                 (long long)events.command_id, 1L);
      cai_error_cleanup(&write.error);
      cai_error_cleanup(&error);
      cai_error_init(&error);
      expect_int(state, "terminal_operation_next_command",
                 cai_tool_registry_run(registry, CAI_TERMINAL_EXEC_TOOL_NAME,
                                       "{\"cmd\":\"printf next\","
                                       "\"yield_time_ms\":100}",
                                       sink, &error),
                 CAI_OK);
    }
  }
  cai_sink_close(sink);
  cai_tool_registry_destroy(registry);
  cai_error_cleanup(&error);
  rmdir(dir_template);
}

static void test_revgeo_tool_decimal_locale(test_state *state,
                                            write_state *writer,
                                            cai_error *error) {
  static const char *const comma_locales[] = {
      "sv_SE.UTF-8", "de_DE.UTF-8", "fr_FR.UTF-8", "es_ES.UTF-8",
      "it_IT.UTF-8", "nl_NL.UTF-8", "da_DK.UTF-8", "fi_FI.UTF-8"};
  char saved_locale[128];
  const char *current_locale;
  const char *selected_locale;
  size_t i;

  current_locale = setlocale(LC_NUMERIC, NULL);
  if (current_locale != NULL) {
    snprintf(saved_locale, sizeof(saved_locale), "%s", current_locale);
    saved_locale[sizeof(saved_locale) - 1U] = '\0';
  } else {
    snprintf(saved_locale, sizeof(saved_locale), "%s", "C");
  }
  selected_locale = NULL;
  for (i = 0U; i < sizeof(comma_locales) / sizeof(comma_locales[0]); i++) {
    if (setlocale(LC_NUMERIC, comma_locales[i]) != NULL) {
      if (localeconv() != NULL && localeconv()->decimal_point != NULL &&
          strcmp(localeconv()->decimal_point, ",") == 0) {
        selected_locale = comma_locales[i];
        break;
      }
    }
  }
  if (selected_locale == NULL) {
    setlocale(LC_NUMERIC, saved_locale);
    return;
  }
  run_mock_revgeo_tool(state, "revgeo_decimal_locale", 0, 0U, CAI_OK, writer,
                       error);
  setlocale(LC_NUMERIC, saved_locale);
}

static void test_revgeo_tool(test_state *state) {
  cai_tool_registry *registry;
  cai_sink_callbacks callbacks;
  cai_sink *sink;
  write_state writer;
  cai_error error;

  cai_error_init(&error);
  registry = NULL;
  sink = NULL;

  run_mock_revgeo_tool(state, "revgeo_success", 0, 0U, CAI_OK, &writer, &error);
  if (strstr(writer.buffer, "\"provider\":\"nominatim\"") == NULL ||
      strstr(writer.buffer, "\"city\":\"Goteborg\"") == NULL ||
      strstr(writer.buffer, "\"municipality\":\"Goteborg\"") == NULL ||
      strstr(writer.buffer, "\"region\":\"Vastra Gotaland\"") == NULL ||
      strstr(writer.buffer, "\"country\":\"Sweden\"") == NULL ||
      strstr(writer.buffer, "\"country_code\":\"se\"") == NULL ||
      strstr(writer.buffer, "\"latitude\":57.708") == NULL ||
      strstr(writer.buffer, "\"longitude\":11.97456") == NULL) {
    test_fail(state, "revgeo_success_body",
              "reverse-geocoding result missing expected fields");
  }
  expect_valid_json(state, "revgeo_success_json", writer.buffer);
  test_revgeo_tool_decimal_locale(state, &writer, &error);
  cai_error_cleanup(&error);
  cai_error_init(&error);

  run_mock_revgeo_tool(state, "revgeo_partial", 1, 0U, CAI_OK, &writer, &error);
  if (strstr(writer.buffer, "\"label\":\"Unknown place\"") == NULL ||
      strstr(writer.buffer, "\"city\":\"\"") == NULL ||
      strstr(writer.buffer, "\"country_code\":\"\"") == NULL) {
    test_fail(state, "revgeo_partial_body",
              "partial reverse-geocoding response was not normalized");
  }
  expect_valid_json(state, "revgeo_partial_json", writer.buffer);
  cai_error_cleanup(&error);
  cai_error_init(&error);

  expect_int(state, "revgeo_registry_new",
             cai_tool_registry_new(&registry, &error), CAI_OK);
  expect_int(state, "revgeo_registry_register",
             cai_tool_registry_register_revgeo_tool(registry, NULL, &error),
             CAI_OK);
  if (cai_tool_registry_schema_at(registry, 0U) == NULL ||
      strstr(cai_tool_registry_schema_at(registry, 0U), "\"latitude\"") ==
          NULL ||
      strstr(cai_tool_registry_schema_at(registry, 0U), "\"longitude\"") ==
          NULL ||
      strstr(cai_tool_registry_schema_at(registry, 0U),
             "\"required\":[\"latitude\",\"longitude\"]") == NULL) {
    test_fail(state, "revgeo_schema", "schema missing coordinate requirements");
  }
  writer.buffer[0] = '\0';
  writer.length = 0U;
  writer.closed = 0;
  callbacks.write = test_write;
  callbacks.close = test_write_close;
  callbacks.context = &writer;
  expect_int(state, "revgeo_sink",
             cai_sink_from_callbacks(&callbacks, &sink, &error), CAI_OK);
  expect_int(state, "revgeo_bad_latitude",
             cai_tool_registry_run(registry, "reverse_geocode",
                                   "{\"latitude\":91.0,\"longitude\":11.97456}",
                                   sink, &error),
             CAI_ERR_INVALID);
  cai_sink_close(sink);
  sink = NULL;
  cai_tool_registry_destroy(registry);
  registry = NULL;
  cai_error_cleanup(&error);
  cai_error_init(&error);

  run_mock_revgeo_tool(state, "revgeo_server_error", 2, 0U, CAI_ERR_SERVER,
                       &writer, &error);
  expect_int(state, "revgeo_server_error_status", error.http_status, 500L);
  cai_error_cleanup(&error);
  cai_error_init(&error);

  run_mock_revgeo_tool(state, "revgeo_malformed", 3, 0U, CAI_ERR_PROTOCOL,
                       &writer, &error);
  cai_error_cleanup(&error);
  cai_error_init(&error);

  run_mock_revgeo_tool(state, "revgeo_response_limit", 4, 64U,
                       CAI_ERR_TRANSPORT, &writer, &error);
  cai_error_cleanup(&error);
}

static int test_lock_file_exclusive(const char *path, int *fd_out) {
  struct flock lock;
  int fd;

  fd = open(path, O_CREAT | O_RDWR, 0600);
  if (fd < 0) {
    return -1;
  }
  memset(&lock, 0, sizeof(lock));
  lock.l_type = F_WRLCK;
  lock.l_whence = SEEK_SET;
  if (fcntl(fd, F_SETLK, &lock) != 0) {
    close(fd);
    return -1;
  }
  *fd_out = fd;
  return 0;
}

static void test_unlock_file_exclusive(int fd) {
  struct flock lock;

  if (fd < 0) {
    return;
  }
  memset(&lock, 0, sizeof(lock));
  lock.l_type = F_UNLCK;
  lock.l_whence = SEEK_SET;
  (void)fcntl(fd, F_SETLK, &lock);
  close(fd);
}

static void test_todo_add_item_child(const char *store_path,
                                     const char *lock_path) {
  cai_todo_tool_config config;
  cai_tool_registry *registry;
  cai_sink_callbacks sink_callbacks;
  cai_sink *sink;
  write_state writer;
  cai_error error;
  int rc;

  cai_error_init(&error);
  registry = NULL;
  sink = NULL;
  memset(&config, 0, sizeof(config));
  memset(&writer, 0, sizeof(writer));
  config.store_path = store_path;
  config.lock_path = lock_path;
  config.default_board = "main";
  sink_callbacks.write = test_write;
  sink_callbacks.close = test_write_close;
  sink_callbacks.context = &writer;
  rc = cai_tool_registry_new(&registry, &error);
  if (rc == CAI_OK) {
    rc = cai_tool_registry_register_todo_tool(registry, &config, &error);
  }
  if (rc == CAI_OK) {
    rc = cai_sink_from_callbacks(&sink_callbacks, &sink, &error);
  }
  if (rc == CAI_OK) {
    rc = cai_tool_registry_run(
        registry, CAI_TODO_DEFAULT_TOOL_NAME,
        "{\"operation\":\"add_item\",\"title\":\"child task\"}", sink, &error);
  }
  if (sink != NULL) {
    cai_sink_close(sink);
  }
  cai_tool_registry_destroy(registry);
  cai_error_cleanup(&error);
  if (rc != CAI_OK || strstr(writer.buffer, "\"ok\":true") == NULL ||
      strstr(writer.buffer, "\"item_id\":\"DEF-001\"") == NULL) {
    _exit(1);
  }
  _exit(0);
}

static void test_todo_file_store_initializes_under_lock(test_state *state) {
  char dir_template[] = "/tmp/cai-todo-lock-test-XXXXXX";
  char store_path[PATH_MAX];
  char lock_path[PATH_MAX];
  char store_text[2048];
  pid_t pid;
  int lock_fd;
  int status;
  int i;
  int store_created_while_locked;

  lock_fd = -1;
  store_created_while_locked = 0;
  if (mkdtemp(dir_template) == NULL) {
    test_fail(state, "todo_lock_mkdtemp", "mkdtemp failed");
    return;
  }
  snprintf(store_path, sizeof(store_path), "%s/todo.json", dir_template);
  snprintf(lock_path, sizeof(lock_path), "%s/todo.lock", dir_template);
  if (test_lock_file_exclusive(lock_path, &lock_fd) != 0) {
    test_fail(state, "todo_lock_parent", "failed to acquire parent lock");
    return;
  }
  pid = fork();
  if (pid < 0) {
    test_unlock_file_exclusive(lock_fd);
    test_fail(state, "todo_lock_fork", "fork failed");
    return;
  }
  if (pid == 0) {
    test_todo_add_item_child(store_path, lock_path);
  }
  for (i = 0; i < 50; i++) {
    if (access(store_path, F_OK) == 0) {
      store_created_while_locked = 1;
      break;
    }
    {
      struct timespec delay;

      delay.tv_sec = 0;
      delay.tv_nsec = 10000000L;
      nanosleep(&delay, NULL);
    }
  }
  if (store_created_while_locked) {
    test_fail(state, "todo_lock_store_init",
              "todo store was initialized before the file lock was acquired");
  }
  test_unlock_file_exclusive(lock_fd);
  lock_fd = -1;
  status = 0;
  if (waitpid(pid, &status, 0) != pid || !WIFEXITED(status) ||
      WEXITSTATUS(status) != 0) {
    test_fail(state, "todo_lock_child", "child todo operation failed");
  }
  if (!read_text_file(store_path, store_text, sizeof(store_text)) ||
      strstr(store_text, "child task") == NULL ||
      strstr(store_text, "DEF-001") == NULL) {
    test_fail(state, "todo_lock_store_content",
              "locked child operation did not persist expected todo item");
  }
}

