static void test_stream_upload_setup_failure(test_state *state) {
  cai_client_config config;
  cai_agent_config agent_config;
  cai_client *client;
  cai_agent *agent;
  cai_session *session;
  cai_sink_callbacks sink_callbacks;
  cai_sink *sink;
  write_state writer;
  cai_error error;
  fail_alloc_state alloc_state;
  lonejson_spooled text;
  lonejson_error json_error;
  int active_before;

  client = NULL;
  agent = NULL;
  session = NULL;
  sink = NULL;
  memset(&writer, 0, sizeof(writer));
  memset(&alloc_state, 0, sizeof(alloc_state));
  alloc_state.fail_after = (size_t)-1;
  cai_error_init(&error);
  lonejson_error_init(&json_error);
  CAI_LJ->spooled_init(CAI_LJ, &text);
  cai_client_config_init(&config);
  config.api_key = "mock-key";
  config.base_url = "http://127.0.0.1:1/v1";
  config.http_2_disabled = 1;
  config.allocator.malloc_fn = test_fail_allocator_malloc;
  config.allocator.realloc_fn = test_fail_allocator_realloc;
  config.allocator.free_fn = test_fail_allocator_free;
  config.allocator.context = &alloc_state;
  cai_agent_config_init(&agent_config);
  agent_config.model = CAI_MODEL_GPT_5_NANO;
  sink_callbacks.write = test_write;
  sink_callbacks.close = test_write_close;
  sink_callbacks.context = &writer;

  expect_int(state, "stream_upload_setup_client_open",
             cai_client_open(&config, &client, &error), CAI_OK);
  expect_int(state, "stream_upload_setup_agent",
             cai_client_new_agent(client, &agent_config, &agent, &error),
             CAI_OK);
  expect_int(state, "stream_upload_setup_session",
             cai_agent_new_session(agent, &session, &error), CAI_OK);
  expect_int(state, "stream_upload_setup_sink",
             cai_sink_from_callbacks(&sink_callbacks, &sink, &error), CAI_OK);
  expect_int(state, "stream_upload_setup_spool_append",
             text.append(&text, "large spooled streaming setup failure input",
                         strlen("large spooled streaming setup failure input"),
                         &json_error),
             LONEJSON_STATUS_OK);
  expect_int(state, "stream_upload_setup_add",
             session->add_user_text_spooled(session, &text, &error), CAI_OK);

  active_before = cai_test_response_request_upload_active();
  alloc_state.fail_after = alloc_state.allocs;
  expect_int(state, "stream_upload_setup_run",
             cai_session_stream_text(session, sink, &error), CAI_ERR_NOMEM);
  expect_str(state, "stream_upload_setup_error", error.message,
             "failed to allocate URL");
  expect_int(state, "stream_upload_setup_active_uploads",
             cai_test_response_request_upload_active(), (long)active_before);

  cai_sink_close(sink);
  cai_session_destroy(session);
  cai_agent_destroy(agent);
  cai_client_close(client);
  cai_error_cleanup(&error);
  expect_int(state, "stream_upload_setup_alloc_balance", alloc_state.frees,
             (long)alloc_state.allocs);
}

