  if (pid == 0) {
    close(pipe_fds[0]);
    mock_openai_child(pipe_fds[1], 4);
  }
  close(pipe_fds[1]);
  nread = read(pipe_fds[0], &port, sizeof(port));
  close(pipe_fds[0]);
  if (nread != (ssize_t)sizeof(port)) {
    test_fail(state, "stream_history_mock", "failed to read mock port");
    waitpid(pid, &child_status, 0);
    return;
  }

